<script setup>
import { onMounted, ref } from 'vue';
import api from '../../lib/api';
const data = ref(null); const error = ref('');
const max = (items) => Math.max(1, ...items.map((item) => item.views));
onMounted(async () => { try { data.value = (await api.get('/management/analytics')).data.data; } catch { error.value = 'Analytics could not be loaded.'; } });
</script>
<template><section class="ds-card p-5"><div class="mb-4 flex items-baseline justify-between"><h2 class="font-black text-navy">روند بازدید ۱۴ روز اخیر</h2><span v-if="data" class="text-xs text-muted">{{ data.totals.views_14d.toLocaleString() }} بازدید</span></div><p v-if="error" class="text-sm text-muted">{{ error }}</p><template v-else-if="data"><div class="flex h-32 items-end gap-1" aria-label="نمودار بازدید"><div v-for="point in data.series" :key="point.date" class="group flex min-w-0 flex-1 flex-col items-center justify-end"><span class="mb-1 hidden rounded bg-navy px-1 text-[10px] text-white group-hover:block">{{ point.views }}</span><i class="w-full rounded-t bg-brand-red/80" :style="{ height: `${Math.max(4, (point.views / max(data.series)) * 100)}%` }"></i></div></div><div class="mt-5 grid gap-2 sm:grid-cols-2"><RouterLink v-for="article in data.top_articles" :key="article.id" :to="`/articles/${article.slug}`" class="flex items-center justify-between rounded-lg bg-cream px-3 py-2 text-xs"><span class="truncate font-bold">{{ article.title }}</span><span class="mr-2 shrink-0 text-muted">{{ article.views.toLocaleString() }}</span></RouterLink></div></template><div v-else class="space-y-4" aria-busy="true"><i class="ds-skeleton block h-32 w-full"></i><div class="grid gap-2 sm:grid-cols-2"><i v-for="item in 4" :key="item" class="ds-skeleton h-9 w-full"></i></div></div></section></template>
